export enum LimitType {
  LIMIT_2 = 2,
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_9 = 9,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
  LIMIT_15 = 15,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export type TuningSystem = 'ji' | 'et' | 'indian' | 'pythagorean';

export type LayoutApproach = 
  | 'lattice' | 'diamond' | 'row' | 'honeycomb' // JI specific
  | 'et_wheel' | 'et_grid' | 'et_row'           // ET specific
  | 'indian_circle' | 'indian_thaat'           // Indian specific
  | 'pyth_spiral' | 'pyth_row';                // Pythagorean specific

export type BackgroundMode = 'rainbow' | 'charcoal' | 'midnight_blue' | 'deep_maroon' | 'forest_green' | 'slate_grey' | 'image' | 'none';

export interface LimitColorMap {
  [key: number]: string;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
  voiceMode?: PlayMode; // The mode/patch used when this note was saved
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
  soundConfig?: SynthPreset; // Legacy single patch
  soundConfigs?: Partial<Record<PlayMode, SynthPreset>>; // New multi-patch storage
}

export interface ArpeggioStep {
    nodeId: string;
    ratio: number;
    n?: number;
    d?: number;
    muted?: boolean;
    limit?: number; // For quality indication (maxPrime)
}

export type ArpDirection = 'order' | 'up' | 'down' | 'updown' | 'random';
export type ArpDivision = '1/1' | '1/2' | '1/4' | '1/8' | '1/16' | '1/32' | '1/4T' | '1/8T' | '1/16T';

export interface ArpConfig {
    direction: ArpDirection;
    division: ArpDivision;
    octaves: number; // 1 to 4
    gate: number; // 0.1 to 1.0
    swing: number; // 0 to 100
    length: number; // 1 to 32 (Pattern Length)
    probability: number; // 0.0 to 1.0 (Chance to play)
    humanize: number; // 0 to 100 (ms of jitter)
}

export interface ArpeggioDefinition {
    id: string; // "A" - "G"
    steps: ArpeggioStep[];
    isPlaying: boolean;
    config: ArpConfig;
}

export interface XYPos {
  x: number;
  y: number;
}

export interface KeyMappings {
    // Navigation & View
    center: string;
    increaseDepth: string;
    decreaseDepth: string;
    settings: string;

    // Global & Panic
    volumeUp: string;
    volumeDown: string;
    panic: string;
    off: string;

    // Patch & Mode Controls (Bottom Right Priority)
    latch: string; // Toggle Drone/Strings mode
    sustain: string; // Toggles Sustain (SUST)
    bend: string; // Toggles Pitch Bend
    modeDrone: string; // Switch to Drone Mode
    modeStrings: string; // Switch to Strings Mode
    modePlucked: string; // Switch to Plucked Mode
    modeVoice: string; // Switch to Voice Mode (New)
    synth: string; // Toggle Synth Panel

    // Chords & Performance
    addChord: string;

    // Tempo
    bpmUp: string;
    bpmDown: string;

    // Arpeggiator
    toggleSequencer: string;
    playAllArps: string;
    stopAllArps: string;

    // Legacy / View scaling (kept for compatibility)
    spatialScaleUp: string;
    spatialScaleDown: string;
}

export interface AppSettings {
  // Global Tuning
  tuningSystem: TuningSystem;
  layoutApproach: LayoutApproach;
  activeSkin: string; // Dynamic skin ID for visual presentation

  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    9: number;
    11: number;
    13: number;
    15: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    9: number;
    11: number;
    13: number;
    15: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons

  // Arpeggios
  arpeggios: ArpeggioDefinition[];
  arpBpm: number;

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1
  audioLatencyHint: 'interactive' | 'balanced' | 'playback'; // Buffer size control
  enableOversampling: boolean; // New: Performance vs Quality toggle
  wavetableSize: 2048 | 8192 | 65536; // Wavetable resolution
  interpolationType: 'linear' | 'cubic'; // Wavetable interpolation method

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Appearance
  baseLineWidth: number; // 0.5 to 3.0 (Static lines)
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2
  lineBrighteningWidth: number; // 1.0 to 4.0

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  limitVisuals?: { [key: number]: { size: number; opacity: number } };

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isSustainEnabled: boolean; // Global Sustain Modifier (Gate vs Latch)
  isStrumEnabled: boolean; // Global Strum Modifier (Trigger vs Gate)
  chordsAlwaysRelatch: boolean; // New: Whether selecting a chord always retriggers/relatches its notes
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Background
  backgroundMode: BackgroundMode;
  backgroundImageData: string | null; // Base64 string for custom image
  backgroundTiling: boolean; // True = Repeat, False = No Repeat (Centered)
  backgroundYOffset: number; // Vertical offset in pixels

  // Legacy Rainbow params (still used if mode is 'rainbow')
  isRainbowModeEnabled: boolean; 
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)

  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // Behavior
  enableKeyboardShortcuts: boolean;
  keyMappings: KeyMappings;
  strumDuration: number; // seconds, 0.1 to 2.0
  recordScreenActivity: boolean; // New Setting: Toggle for video capture

  // UI Relocation & Scaling
  uiUnlocked: boolean;
  uiScale: number; // 0.5 (Tiny) to 1.5 (Huge)
  uiEdgeMargin: number; // in Millimeters (1-10)
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos; // Legacy key, kept for data compatibility, now usually unused or re-mapped
    sust: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
    arpeggioBar: XYPos;
    instruments: XYPos; // New cluster for Drone/String
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;
  category?: string; // New field for categorization

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Stereo & Pan
  spread?: number; // 0 to 1 (Voice Stereo Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)

  // Reverb Unit
  reverbType?: ReverbType; // Convolution Preset (Logic base)
  reverbMix: number; // 0 to 1
  reverbSize: number; // Duration in seconds (0.1 to 10.0)
  reverbDamping: number; // 0 (Bright) to 1 (Dark)
  reverbDiffusion?: number; // 0 (Grainy) to 1 (Smooth)

  // Delay Unit
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds

  // Arp Settings
  arpConfig?: ArpConfig;
}

// Slot Types
export type PresetSlot = 'normal' | 'latch' | 'strum' | 'voice' | 'arpeggio';
export type PlayMode = PresetSlot; // Alias for backward compatibility
export type PlaybackMode = 'gate' | 'trigger' | 'latch'; // Behavior type

export interface PresetState {
    normal: SynthPreset;
    latch: SynthPreset;
    strum: SynthPreset;
    voice: SynthPreset;
    arpeggio: SynthPreset;
}

export interface StoreState {
    settings: AppSettings;
    presets: PresetState;
    userBank: SynthPreset[]; // 20 Save Slots
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p9, p11, p13, p15]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

import { SynthPreset, AppSettings, ReverbType, PresetState, PlayMode, PlaybackMode } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET, REVERB_DEFAULTS } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';

// --- Typed Messages for Worklet ---
interface WorkletMessageBase {
    type: string;
}

interface UpdatePresetMessage extends WorkletMessageBase {
    type: 'update_preset';
    mode: string;
    data: any; // Normalized preset
}

interface ConfigMessage extends WorkletMessageBase {
    type: 'config';
    polyphony?: number;
    strumDuration?: number;
    enableOversampling?: boolean;
    globalBend?: number;
    wavetableSize?: number;
    interpolationType?: 'linear' | 'cubic';
}

interface NoteOnMessage extends WorkletMessageBase {
    type: 'note_on';
    id: string;
    freq: number;
    voiceType: string;
    mode: PlaybackMode;
}

interface NoteOffMessage extends WorkletMessageBase {
    type: 'note_off';
    id: string;
}

interface GlideMessage extends WorkletMessageBase {
    type: 'glide';
    id: string;
    freq: number;
}

interface StopAllMessage extends WorkletMessageBase {
    type: 'stop_all';
}

type AudioWorkletMessage = UpdatePresetMessage | ConfigMessage | NoteOnMessage | NoteOffMessage | GlideMessage | StopAllMessage;

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // Message Queue for pre-init commands
  private messageQueue: AudioWorkletMessage[] = [];

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private masterFilter: BiquadFilterNode | null = null; // New Tone Control
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  // Final Output Stage
  private finalMasterGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private globalBrightness: number = 1.0; // 0.0 to 1.0

  // Cache active presets for FX updates
  private activePresets: PresetState;

  private voiceStealListeners: Set<(id: string) => void> = new Set();

  constructor() {
    // Initialize Presets safely
    const rawPresets = store.getSnapshot().presets;
    this.activePresets = {
        normal: this.ensurePresetSafety(rawPresets.normal),
        latch: this.ensurePresetSafety(rawPresets.latch),
        strum: this.ensurePresetSafety(rawPresets.strum),
        voice: this.ensurePresetSafety(rawPresets.voice),
        arpeggio: this.ensurePresetSafety(rawPresets.arpeggio)
    };

    // Auto-init to pre-load audio resources immediately
    this.init().catch(e => console.warn("Auto-init postponed (will retry on gesture)", e));

    store.subscribe(() => {
        const newPresets = store.getSnapshot().presets;
        this.updatePresets(newPresets);
    });
  }

  public onVoiceSteal(callback: (id: string) => void) {
      this.voiceStealListeners.add(callback);
      return () => { this.voiceStealListeners.delete(callback); };
  }

  private isMobile() {
      return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;

     const validReverbTypes: ReverbType[] = ['room', 'hall', 'cathedral', 'plate', 'shimmer'];
     let rType: ReverbType = 'hall';

     if (p.reverbType && validReverbTypes.includes(p.reverbType)) {
         rType = p.reverbType as ReverbType;
     }

     const safe: SynthPreset = {
         ...DEFAULT_PRESET,
         ...p,
         osc1: { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) },
         osc2: { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) },
         osc3: { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) },
         modMatrix: p.modMatrix || [],
         reverbType: rType
     };

     const defaults = REVERB_DEFAULTS[rType];
     if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;

     return safe;
  }

  private postMessage(msg: AudioWorkletMessage) {
      if (this.workletNode) {
          this.workletNode.port.postMessage(msg);
      } else {
          this.messageQueue.push(msg);
          // If we are queuing messages but not initializing, trigger init
          if (!this.initPromise && !this.ctx) {
              this.init();
          }
      }
  }

  public updateSettings(settings: AppSettings) {
      this.postMessage({ 
          type: 'config', 
          polyphony: settings.polyphony,
          strumDuration: settings.strumDuration,
          enableOversampling: settings.enableOversampling,
          wavetableSize: settings.wavetableSize,
          interpolationType: settings.interpolationType
      });
  }

  public updatePresets(newPresets: PresetState) {
      const modes: PlayMode[] = ['normal', 'latch', 'strum', 'voice', 'arpeggio'];
      let recomputeReverb = false;

      const oldMaster = this.activePresets.normal;
      const newMaster = newPresets.normal;

      if (
          oldMaster.reverbType !== newMaster.reverbType ||
          oldMaster.reverbSize !== newMaster.reverbSize ||
          oldMaster.reverbDamping !== newMaster.reverbDamping ||
          oldMaster.reverbDiffusion !== newMaster.reverbDiffusion
      ) {
          recomputeReverb = true;
      }

      this.activePresets = {
          normal: this.ensurePresetSafety(newPresets.normal),
          latch: this.ensurePresetSafety(newPresets.latch),
          strum: this.ensurePresetSafety(newPresets.strum),
          voice: this.ensurePresetSafety(newPresets.voice),
          arpeggio: this.ensurePresetSafety(newPresets.arpeggio)
      };

      if (recomputeReverb && this.ctx) {
          this.updateReverbBuffer();
      }
      this.updateFX();

      // If worklet isn't ready, these will be queued by postMessage
      modes.forEach(mode => {
          this.postMessage({ 
              type: 'update_preset', 
              mode: mode, 
              data: this.activePresets[mode] 
          });
      });
  }

  // New Method: Register a dynamic preset (like a chord patch) with the audio engine
  public registerPreset(id: string, preset: SynthPreset) {
      this.postMessage({
          type: 'update_preset',
          mode: id,
          data: this.ensurePresetSafety(preset)
      });
  }

  public async resume() {
      if (!this.ctx) {
          await this.init(); 
      }
      if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
          try {
            await this.ctx.resume();
          } catch (e) {
            // Harmless warning if called before gesture
            // console.warn("Context resume pending gesture");
          }
      }
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const settings = store.getSnapshot().settings;
            const latencyHint = settings.audioLatencyHint || 'playback';

            this.ctx = new AudioContextClass({
                latencyHint: latencyHint,
            });

            this.ctx.onstatechange = () => {
                if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
                    // Try to auto-resume if allowed
                    this.ctx.resume().catch(() => {}); 
                }
            };

            try {
                // Use Blob URL to load worklet code reliably
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const url = URL.createObjectURL(blob);

                await this.ctx.audioWorklet.addModule(url);
                URL.revokeObjectURL(url);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                // Set up message handler for voice stealing events
                this.workletNode.port.onmessage = (e) => {
                    if (e.data.type === 'voice_stolen') {
                        this.voiceStealListeners.forEach(cb => cb(e.data.id));
                    }
                };

                // Initialize state from store
                (['normal', 'latch', 'strum', 'voice', 'arpeggio'] as PlayMode[]).forEach(mode => {
                    this.workletNode!.port.postMessage({ 
                        type: 'update_preset', 
                        mode: mode, 
                        data: this.activePresets[mode] 
                    });
                });

                const currentSettings = store.getSnapshot().settings;
                this.workletNode!.port.postMessage({ 
                    type: 'config', 
                    polyphony: currentSettings.polyphony,
                    strumDuration: currentSettings.strumDuration,
                    enableOversampling: currentSettings.enableOversampling,
                    wavetableSize: currentSettings.wavetableSize,
                    interpolationType: currentSettings.interpolationType
                });

                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

                // Flush Queue
                if (this.messageQueue.length > 0) {
                    this.messageQueue.forEach(msg => this.workletNode!.port.postMessage(msg));
                    this.messageQueue = [];
                }

                console.log("Audio Engine Initialized (Suspended)");

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        // We do NOT auto-resume here anymore to allow constructor init without gesture
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx) return;

    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
        this.masterFilter?.disconnect();
        this.finalMasterGain?.disconnect();
    } catch(e) { /* ignore */ }

    // Master Filter (Tone Control)
    this.masterFilter = this.ctx.createBiquadFilter();
    this.masterFilter.type = 'lowpass';
    this.masterFilter.frequency.value = 20000;
    this.masterFilter.Q.value = 0.5;

    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -8.0; 
    this.limiter.ratio.value = 10.0;
    this.limiter.attack.value = 0.005;

    // Final Master Gain (Global Volume)
    this.finalMasterGain = this.ctx.createGain();
    this.finalMasterGain.gain.value = this.currentMasterVol;

    // Filter -> Limiter -> FinalGain -> Destination
    this.masterFilter.connect(this.limiter);
    this.limiter.connect(this.finalMasterGain);
    this.finalMasterGain.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.masterFilter);

    this.reverbNode = this.ctx.createConvolver();
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.masterFilter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.masterFilter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    // Reconnect Worklet if it exists
    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;

      const master = this.activePresets.normal;
      const type = master.reverbType || 'hall';

      const duration = master.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = master.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = master.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': decay = 3.0; density = 0.8; break;
          case 'hall': decay = 2.0; density = 0.6; preDelay = 0.02; break;
          case 'cathedral': decay = 1.5; density = 0.4; preDelay = 0.04; break;
          case 'plate': decay = 4.0; density = 1.0; break;
          case 'shimmer': decay = 0.8; density = 0.2; break;
          default: decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      const master = this.activePresets.normal;

      const scaledReverbMix = Math.min(1.0, master.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, master.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, master.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(master.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = master.compressorThreshold ?? -20.0;
          const ratio = master.compressorRatio ?? 12;
          const release = master.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.masterFilter) {
          // Logarithmic mapping for brightness: 0..1 -> 100Hz .. 20000Hz
          const minFreq = 100;
          const maxFreq = 20000;
          const freq = minFreq * Math.pow(maxFreq/minFreq, this.globalBrightness);
          this.masterFilter.frequency.setTargetAtTime(freq, now, ramp);
      }

      if (this.finalMasterGain) {
          this.finalMasterGain.gain.setTargetAtTime(this.currentMasterVol, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          // Normalized dry level logic, volume now handled by finalMasterGain
          this.dryGain.gain.setTargetAtTime(dryLevel, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    const startSample = Math.floor(preDelay * sampleRate);
    let lpL = 0, lpR = 0;
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);
        const progress = (i - startSample) / (length - startSample);
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        const env = Math.pow(1 - progress, decayCurve);
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      this.postMessage({ type: 'config', polyphony: count });
  }

  public setStrumDuration(duration: number) {
      this.postMessage({ type: 'config', strumDuration: duration });
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public setGlobalBrightness(val: number) {
      this.globalBrightness = val;
      this.updateFX();
  }

  // New method for global pitch bend
  public setGlobalBend(semitones: number) {
      const ratio = Math.pow(2, semitones / 12.0);
      this.postMessage({ type: 'config', globalBend: ratio });
  }

  public getContext(): AudioContext | null {
      return this.ctx;
  }

  // Allow connecting the master output to an external destination (e.g. MediaStreamDestination for recording)
  public connectToRecordingDestination(destination: AudioNode) {
      if (this.finalMasterGain) {
          // Connect in parallel to the recording destination
          this.finalMasterGain.connect(destination);
      }
  }

  // Updated startVoice: No longer awaits init(). Queues message if needed.
  public startVoice(id: string, ratio: number, baseFrequency: number, presetSlot: string = 'normal', playbackMode: PlaybackMode = 'gate') {
    // Ensure context is running (resume if suspended)
    this.resume();

    const freq = baseFrequency * ratio;
    this.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq,
        voiceType: presetSlot,
        mode: playbackMode
    });
  }

  public stopVoice(id: string) {
    this.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number) {
    const freq = baseFrequency * newRatio;
    this.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    this.postMessage({ type: 'stop_all' });
    // Resetting FX is safe to do immediately even if audio isn't running
    if (this.ctx) this.setupFX();
  }
}

