// --- Typed Messages for Worklet ---
interface WorkletMessageBase {
    type: string;
}

interface UpdatePresetMessage extends WorkletMessageBase {
    type: 'update_preset';
    mode: string;
    data: any; // Normalized preset
}

interface ConfigMessage extends WorkletMessageBase {
    type: 'config';
    polyphony?: number;
    strumDuration?: number;
    enableOversampling?: boolean;
    globalBend?: number;
    wavetableSize?: number;
    interpolationType?: 'linear' | 'cubic';
}

interface NoteOnMessage extends WorkletMessageBase {
    type: 'note_on';
    id: string;
    freq: number;
    voiceType: string;
    mode: PlaybackMode;
}

interface NoteOffMessage extends WorkletMessageBase {
    type: 'note_off';
    id: string;
}

interface GlideMessage extends WorkletMessageBase {
    type: 'glide';
    id: string;
    freq: number;
}

interface StopAllMessage extends WorkletMessageBase {
    type: 'stop_all';
}

type AudioWorkletMessage = UpdatePresetMessage | ConfigMessage | NoteOnMessage | NoteOffMessage | GlideMessage | StopAllMessage;

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // Message Queue for pre-init commands
  private messageQueue: AudioWorkletMessage[] = [];

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private masterFilter: BiquadFilterNode | null = null; // New Tone Control
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  // Final Output Stage
  private finalMasterGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private globalBrightness: number = 1.0; // 0.0 to 1.0

  // Cache active presets for FX updates
  private activePresets: PresetState;

  private voiceStealListeners: Set<(id: string) => void> = new Set();

  constructor() {
    // Initialize Presets safely
    const rawPresets = store.getSnapshot().presets;
    this.activePresets = {
        normal: this.ensurePresetSafety(rawPresets.normal),
        latch: this.ensurePresetSafety(rawPresets.latch),
        strum: this.ensurePresetSafety(rawPresets.strum),
        voice: this.ensurePresetSafety(rawPresets.voice),
        arpeggio: this.ensurePresetSafety(rawPresets.arpeggio)
    };

    // Auto-init to pre-load audio resources immediately
    this.init().catch(e => console.warn("Auto-init postponed (will retry on gesture)", e));

    store.subscribe(() => {
        const newPresets = store.getSnapshot().presets;
        this.updatePresets(newPresets);
    });
  }

  public onVoiceSteal(callback: (id: string) => void) {
      this.voiceStealListeners.add(callback);
      return () => { this.voiceStealListeners.delete(callback); };
  }

  private isMobile() {
      return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;

     const validReverbTypes: ReverbType[] = ['room', 'hall', 'cathedral', 'plate', 'shimmer'];
     let rType: ReverbType = 'hall';

     if (p.reverbType && validReverbTypes.includes(p.reverbType)) {
         rType = p.reverbType as ReverbType;
     }

     const safe: SynthPreset = {
         ...DEFAULT_PRESET,
         ...p,
         osc1: { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) },
         osc2: { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) },
         osc3: { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) },
         modMatrix: p.modMatrix || [],
         reverbType: rType,
         aspirationGain: p.aspirationGain !== undefined ? p.aspirationGain : 0,
         aspirationCutoff: p.aspirationCutoff !== undefined ? p.aspirationCutoff : 4000
     };

     const defaults = REVERB_DEFAULTS[rType];
     if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;

     return safe;
  }

  private postMessage(msg: AudioWorkletMessage) {
      if (this.workletNode) {
          this.workletNode.port.postMessage(msg);
      } else {
          this.messageQueue.push(msg);
          // If we are queuing messages but not initializing, trigger init
          if (!this.initPromise && !this.ctx) {
              this.init();
          }
      }
  }

  public updateSettings(settings: AppSettings) {
      this.postMessage({ 
          type: 'config', 
          polyphony: settings.polyphony,
          strumDuration: settings.strumDuration,
          enableOversampling: settings.enableOversampling,
          wavetableSize: settings.wavetableSize,
          interpolationType: settings.interpolationType
      });
  }

  public updatePresets(newPresets: PresetState) {
      const modes: PlayMode[] = ['normal', 'latch', 'strum', 'voice', 'arpeggio'];
      let recomputeReverb = false;

      const oldMaster = this.activePresets.normal;
      const newMaster = newPresets.normal;

      if (
          oldMaster.reverbType !== newMaster.reverbType ||
          oldMaster.reverbSize !== newMaster.reverbSize ||
          oldMaster.reverbDamping !== newMaster.reverbDamping ||
          oldMaster.reverbDiffusion !== newMaster.reverbDiffusion
      ) {
          recomputeReverb = true;
      }

      this.activePresets = {
          normal: this.ensurePresetSafety(newPresets.normal),
          latch: this.ensurePresetSafety(newPresets.latch),
          strum: this.ensurePresetSafety(newPresets.strum),
          voice: this.ensurePresetSafety(newPresets.voice),
          arpeggio: this.ensurePresetSafety(newPresets.arpeggio)
      };

      if (recomputeReverb && this.ctx) {
          this.updateReverbBuffer();
      }
      this.updateFX();

      // If worklet isn't ready, these will be queued by postMessage
      modes.forEach(mode => {
          this.postMessage({ 
              type: 'update_preset', 
              mode: mode, 
              data: this.activePresets[mode] 
          });
      });
  }

  // New Method: Register a dynamic preset (like a chord patch) with the audio engine
  public registerPreset(id: string, preset: SynthPreset) {
      this.postMessage({
          type: 'update_preset',
          mode: id,
          data: this.ensurePresetSafety(preset)
      });
  }

  public async resume() {
      if (!this.ctx) {
          await this.init(); 
      }
      if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
          try {
            await this.ctx.resume();
          } catch (e) {
            // Harmless warning if called before gesture
            // console.warn("Context resume pending gesture");
          }
      }
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const settings = store.getSnapshot().settings;
            const latencyHint = settings.audioLatencyHint || 'playback';

            this.ctx = new AudioContextClass({
                latencyHint: latencyHint,
            });

            this.ctx.onstatechange = () => {
                if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
                    // Try to auto-resume if allowed
                    this.ctx.resume().catch(() => {}); 
                }
            };

            try {
                // Use Blob URL to load worklet code reliably
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const url = URL.createObjectURL(blob);

                await this.ctx.audioWorklet.addModule(url);
                URL.revokeObjectURL(url);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                // Set up message handler for voice stealing events
                this.workletNode.port.onmessage = (e) => {
                    if (e.data.type === 'voice_stolen') {
                        this.voiceStealListeners.forEach(cb => cb(e.data.id));
                    }
                };

                // Initialize state from store
                (['normal', 'latch', 'strum', 'voice', 'arpeggio'] as PlayMode[]).forEach(mode => {
                    this.workletNode!.port.postMessage({ 
                        type: 'update_preset', 
                        mode: mode, 
                        data: this.activePresets[mode] 
                    });
                });

                const currentSettings = store.getSnapshot().settings;
                this.workletNode!.port.postMessage({ 
                    type: 'config', 
                    polyphony: currentSettings.polyphony,
                    strumDuration: currentSettings.strumDuration,
                    enableOversampling: currentSettings.enableOversampling,
                    wavetableSize: currentSettings.wavetableSize,
                    interpolationType: currentSettings.interpolationType
                });

                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

                // Flush Queue
                if (this.messageQueue.length > 0) {
                    this.messageQueue.forEach(msg => this.workletNode!.port.postMessage(msg));
                    this.messageQueue = [];
                }

                console.log("Audio Engine Initialized (Suspended)");

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        // We do NOT auto-resume here anymore to allow constructor init without gesture
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx) return;

    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
        this.masterFilter?.disconnect();
        this.finalMasterGain?.disconnect();
    } catch(e) { /* ignore */ }

    // Master Filter (Tone Control)
    this.masterFilter = this.ctx.createBiquadFilter();
    this.masterFilter.type = 'lowpass';
    this.masterFilter.frequency.value = 20000;
    this.masterFilter.Q.value = 0.5;

    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -8.0; 
    this.limiter.ratio.value = 10.0;
    this.limiter.attack.value = 0.005;

    // Final Master Gain (Global Volume)
    this.finalMasterGain = this.ctx.createGain();
    this.finalMasterGain.gain.value = this.currentMasterVol;

    // Filter -> Limiter -> FinalGain -> Destination
    this.masterFilter.connect(this.limiter);
    this.limiter.connect(this.finalMasterGain);
    this.finalMasterGain.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.masterFilter);

    this.reverbNode = this.ctx.createConvolver();
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.masterFilter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.masterFilter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    // Reconnect Worklet if it exists
    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;

      const master = this.activePresets.normal;
      const type = master.reverbType || 'hall';

      const duration = master.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = master.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = master.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': decay = 3.0; density = 0.8; break;
          case 'hall': decay = 2.0; density = 0.6; preDelay = 0.02; break;
          case 'cathedral': decay = 1.5; density = 0.4; preDelay = 0.04; break;
          case 'plate': decay = 4.0; density = 1.0; break;
          case 'shimmer': decay = 0.8; density = 0.2; break;
          default: decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      const master = this.activePresets.normal;

      const scaledReverbMix = Math.min(1.0, master.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, master.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, master.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(master.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = master.compressorThreshold ?? -20.0;
          const ratio = master.compressorRatio ?? 12;
          const release = master.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.masterFilter) {
          // Logarithmic mapping for brightness: 0..1 -> 100Hz .. 20000Hz
          const minFreq = 100;
          const maxFreq = 20000;
          const freq = minFreq * Math.pow(maxFreq/minFreq, this.globalBrightness);
          this.masterFilter.frequency.setTargetAtTime(freq, now, ramp);
      }

      if (this.finalMasterGain) {
          this.finalMasterGain.gain.setTargetAtTime(this.currentMasterVol, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          // Normalized dry level logic, volume now handled by finalMasterGain
          this.dryGain.gain.setTargetAtTime(dryLevel, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    const startSample = Math.floor(preDelay * sampleRate);
    let lpL = 0, lpR = 0;
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);
        const progress = (i - startSample) / (length - startSample);
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        const env = Math.pow(1 - progress, decayCurve);
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      this.postMessage({ type: 'config', polyphony: count });
  }

  public setStrumDuration(duration: number) {
      this.postMessage({ type: 'config', strumDuration: duration });
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public setGlobalBrightness(val: number) {
      this.globalBrightness = val;
      this.updateFX();
  }

  // New method for global pitch bend
  public setGlobalBend(semitones: number) {
      const ratio = Math.pow(2, semitones / 12.0);
      this.postMessage({ type: 'config', globalBend: ratio });
  }

  public getContext(): AudioContext | null {
      return this.ctx;
  }

  // Allow connecting the master output to an external destination (e.g. MediaStreamDestination for recording)
  public connectToRecordingDestination(destination: AudioNode) {
      if (this.finalMasterGain) {
          // Connect in parallel to the recording destination
          this.finalMasterGain.connect(destination);
      }
  }

  // Updated startVoice: No longer awaits init(). Queues message if needed.
  public startVoice(id: string, ratio: number, baseFrequency: number, presetSlot: string = 'normal', playbackMode: PlaybackMode = 'gate') {
    // Ensure context is running (resume if suspended)
    this.resume();

    const freq = baseFrequency * ratio;
    this.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq,
        voiceType: presetSlot,
        mode: playbackMode
    });
  }

  public stopVoice(id: string) {
    this.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number) {
    const freq = baseFrequency * newRatio;
    this.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    this.postMessage({ type: 'stop_all' });
    // Resetting FX is safe to do immediately even if audio isn't running
    if (this.ctx) this.setupFX();
  }
}

export const audioEngine = new AudioEngine();
export default AudioEngine;

export const AUDIO_PROCESSOR_CODE = `
// --- 1. DSP UTILS & CONSTANTS ---

const TWO_PI = 2 * Math.PI;

// Increased from 4096 to 65536 to eliminate linear interpolation artifacts
const WAVETABLE_SIZE = 65536; 
const SINE_TABLE = new Float32Array(WAVETABLE_SIZE + 1); // +1 for simple interpolation guard
const GLOTTAL_TABLE = new Float32Array(WAVETABLE_SIZE + 1); 

// Precompute Sine Table
for (let i = 0; i <= WAVETABLE_SIZE; i++) {
    const phase = i / WAVETABLE_SIZE;
    SINE_TABLE[i] = Math.sin(phase * TWO_PI);
}

// Precompute Glottal Table (Rosenberg-C approximation via additive synthesis)
// This creates a band-limited pulse with approx -12dB/oct spectral slope
// Rich in even and odd harmonics, perfect for subtractive vocal synthesis.
{
    const numHarmonics = 64;
    for (let i = 0; i <= WAVETABLE_SIZE; i++) {
        let sample = 0;
        const phase = i / WAVETABLE_SIZE;
        for (let k = 1; k <= numHarmonics; k++) {
            // Amplitude falls off as 1/k^1.6 (approx -10dB/oct)
            const amp = 1.0 / Math.pow(k, 1.6);
            // Cosine phase alignment ensures a peak at 0 (Pulse-like)
            sample += amp * Math.cos(k * phase * TWO_PI);
        }
        GLOTTAL_TABLE[i] = sample;
    }
    // Normalize Glottal Table
    let maxVal = 0;
    for (let i = 0; i <= WAVETABLE_SIZE; i++) maxVal = Math.max(maxVal, Math.abs(GLOTTAL_TABLE[i]));
    for (let i = 0; i <= WAVETABLE_SIZE; i++) GLOTTAL_TABLE[i] /= maxVal;
}

// Formant Frequencies (Approximations of Tenor/Soprano)
// A, E, I, O, U
const FORMANTS = [
    { f1: 730, f2: 1090, f3: 2440, g1: 1.0, g2: 0.5, g3: 0.2 }, // A (aa)
    { f1: 530, f2: 1840, f3: 2480, g1: 1.0, g2: 0.4, g3: 0.2 }, // E (eh)
    { f1: 270, f2: 2290, f3: 3010, g1: 1.0, g2: 0.3, g3: 0.1 }, // I (iy)
    { f1: 570, f2: 840,  f3: 2410, g1: 1.0, g2: 0.5, g3: 0.2 }, // O (ow)
    { f1: 300, f2: 870,  f3: 2240, g1: 1.0, g2: 0.4, g3: 0.2 }  // U (uw)
];

const DUMMY_OSC_CONFIG = {
    enabled: false,
    waveform: 'sine',
    coarseDetune: 0,
    fineDetune: 0,
    gain: 0,
    attack: 0.1,
    decay: 0.1,
    sustain: 0,
    release: 0.1,
    filterCutoff: 20000,
    filterResonance: 0,
    filterType: 'lowpass',
    lfoRate: 1,
    lfoDepth: 0,
    lfoTarget: 'none',
    lfoDelay: 0
};

const DUMMY_PRESET_DATA = {
    osc1: DUMMY_OSC_CONFIG,
    osc2: DUMMY_OSC_CONFIG,
    osc3: DUMMY_OSC_CONFIG,
    modMatrix: [],
    gain: 1.0,
    spread: 0,
    stereoPanSpeed: 0,
    stereoPanDepth: 0,
    formantStrength: 0,
    vowel: 0,
    portamento: 0,
    aspirationGain: 0,
    aspirationCutoff: 4000
};

// --- 2. BASIC DSP CLASSES (Oscillator, Filter, Envelope) ---

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate, type, peakGain = 1.0) {
    // Safe Cutoff range: 20Hz to Nyquist (approx)
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.45));

    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    // 0=Low, 1=High, 2=Band, 3=Notch
    if (type === 0) return this.low;
    if (type === 1) return this.high;
    if (type === 2) return this.band;
    if (type === 3) return this.notch;

    // 4=Peak: Mix of Low/High and Band.
    // For a peak filter in SVF: Output = Low + High + (Band * Gain)
    // If Gain is high, we boost at cutoff.
    if (type === 4) {
        return this.low + this.high + (this.band * peakGain);
    }

    // 5=LowShelf: Boost/Cut Lows
    // Output = (Low * Gain) + High + Band
    if (type === 5) {
        return (this.low * peakGain) + this.high + this.band;
    }

    // 6=HighShelf: Boost/Cut Highs
    // Output = Low + (High * Gain) + Band
    if (type === 6) {
        return this.low + (this.high * peakGain) + this.band;
    }

    return this.low; 
  }
}

class FormantFilter {
    constructor() {
        this.f1 = new SVF();
        this.f2 = new SVF();
        this.f3 = new SVF();
        this.currentVowel = -1; // Force update on first run
    }

    reset() {
        this.f1.reset();
        this.f2.reset();
        this.f3.reset();
        this.currentVowel = -1;
    }

    // Interpolate formant params
    process(input, vowel, sampleRate) {
        // Vowel 0-1 maps to A-E-I-O-U
        // Indices: 0, 1, 2, 3, 4
        // scaledVowel = vowel * 4

        const pos = Math.max(0, Math.min(1, vowel)) * 4.0;
        const idx = Math.floor(pos);
        const frac = pos - idx;

        const nextIdx = Math.min(idx + 1, 4);

        const p1 = FORMANTS[idx];
        const p2 = FORMANTS[nextIdx];

        // Linear interpolation of freq
        const f1_freq = p1.f1 + (p2.f1 - p1.f1) * frac;
        const f2_freq = p1.f2 + (p2.f2 - p1.f2) * frac;
        const f3_freq = p1.f3 + (p2.f3 - p1.f3) * frac;

        // Gains
        const g1 = p1.g1 + (p2.g1 - p1.g1) * frac;
        const g2 = p1.g2 + (p2.g2 - p1.g2) * frac;
        const g3 = p1.g3 + (p2.g3 - p1.g3) * frac;

        // Bandpass processing with moderate Q (Resonance ~ 4-8)
        // High Q makes vowels clearer but quieter
        const res = 4.0; 

        const out1 = this.f1.process(input, f1_freq, res, sampleRate, 2); // 2 = Band
        const out2 = this.f2.process(input, f2_freq, res, sampleRate, 2);
        const out3 = this.f3.process(input, f3_freq, res, sampleRate, 2);

        return (out1 * g1) + (out2 * g2) + (out3 * g3);
    }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  reset() {
      // Free-running oscillators
  }

  process(freq, type, dt) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        // High-performance LUT lookup
        {
            const index = this.phase * WAVETABLE_SIZE;
            const i = Math.floor(index);
            const f = index - i;
            // Linear Interpolation from pre-computed table
            sample = SINE_TABLE[i] + f * (SINE_TABLE[i + 1] - SINE_TABLE[i]);
        }
        break;
      case 'glottal':
        {
            const index = this.phase * WAVETABLE_SIZE;
            const i = Math.floor(index);
            const f = index - i;
            // Lookup from new Glottal table
            sample = GLOTTAL_TABLE[i] + f * (GLOTTAL_TABLE[i + 1] - GLOTTAL_TABLE[i]);
        }
        break;
      case 'triangle':
        {
            let t = -1.0 + (2.0 * this.phase);
            sample = 2.0 * (Math.abs(t) - 0.5);
        }
        break;
      case 'sawtooth':
        // PolyBLEP Saw is efficient and sounds good
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;
      case 'square':
        // PolyBLEP Square
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
      case 'noise':
        // Simple White Noise
        sample = (Math.random() * 2.0) - 1.0;
        break;
    }

    return sample;
  }
}

// --- 3. VOICE LOGIC (Signal Path) ---

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.type = 'normal'; // Preset selection
    this.mode = 'gate';   // Playback behavior: 'gate', 'trigger', 'latch'
    this.panPos = 0; 

    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0; 
    this.activeTime = 0.0; // Seconds active, for LFO delay

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.formantFilter = new FormantFilter();
    this.noiseFilter = new SVF(); // Dedicated Aspiration Filter

    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  // Allow dynamic updates to sample rate when oversampling changes
  updateSampleRate(newRate) {
      if (this.sampleRate === newRate) return;
      this.sampleRate = newRate;
      this.oscs.forEach(osc => { osc.sampleRate = newRate; osc.blep.sampleRate = newRate; });
  }

  trigger(id, freq, type, mode) {
    this.id = id;
    this.type = type || 'normal';
    this.mode = mode || 'gate';
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0; 
    this.activeTime = 0.0;

    this.envs.forEach(env => {
        // Soft reset to avoid clicks on retrigger
        env.trigger();
    });

    this.filters.forEach(f => f.reset());
    this.formantFilter.reset();
    this.noiseFilter.reset();
    this.lfoPhases.fill(0.0);
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
      this.formantFilter.reset();
      this.noiseFilter.reset();
  }

  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  // Helper to map string types to integer for optimized loop
  getFilterTypeId(type) {
      if (type === 'highpass') return 1;
      if (type === 'bandpass') return 2;
      if (type === 'notch') return 3;
      if (type === 'peak') return 4;
      if (type === 'lowshelf') return 5;
      if (type === 'highshelf') return 6;
      return 0; // lowpass
  }

  // Optimized block processing
  renderBlock(preset, dt, bufL, bufR, len, panSpeed, panDepth, startPanPhase, globalBend) {
    if (!this.active) return;

    // --- FREQ GLIDE ---
    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
        const glideParam = preset.portamento !== undefined ? preset.portamento : 0;
        let coef = 0.005; // Fallback

        if (glideParam <= 0.01) {
            coef = 1.0; // Instant
        } else {
            const timeConst = glideParam * 0.5; // Up to 0.5s glide
            coef = 1.0 - Math.exp(- (len * dt) / timeConst);
        }

        this.baseFreq += diff * coef;
    } else {
      this.baseFreq = this.targetFreq;
    }

    // --- CACHED CONFIGS ---
    const osc1 = preset.osc1 || DUMMY_OSC_CONFIG;
    const osc2 = preset.osc2 || DUMMY_OSC_CONFIG;
    const osc3 = preset.osc3 || DUMMY_OSC_CONFIG;
    const matrix = preset.modMatrix || [];
    const spreadAmount = preset.spread || 0;
    const voiceGain = preset.gain || 0.5;
    const formantStrength = preset.formantStrength || 0;
    const vowelPos = preset.vowel || 0;
    const aspirationGain = preset.aspirationGain || 0;
    const aspirationCutoff = preset.aspirationCutoff || 4000;
    const hasMatrix = matrix.length > 0;

    // Filter Type Integers
    const fType1 = this.getFilterTypeId(osc1.filterType);
    const fType2 = this.getFilterTypeId(osc2.filterType);
    const fType3 = this.getFilterTypeId(osc3.filterType);

    // --- CHECK FOR VOCAL MODE ---
    // If Osc 1 is GLOTTAL, we switch to Serial Filtering topology
    const isVocalMode = osc1.waveform === 'glottal';

    let anyEnvActive = false;
    let panPhase = startPanPhase;

    // Pre-calculate LFO rates to avoid dictionary lookup in tight loop
    const lfoRate1 = osc1.lfoRate || 0;
    const lfoRate2 = osc2.lfoRate || 0;
    const lfoRate3 = osc3.lfoRate || 0;

    // OPTIMIZATION: Pre-calculate static frequencies if no modulation
    // Apply globalBend to the base frequency here
    let osc1StaticFreq = 0, osc2StaticFreq = 0, osc3StaticFreq = 0;
    let osc1ModPitch = false, osc2ModPitch = false, osc3ModPitch = false;

    // Check for pitch mod in Matrix or LFO
    if (osc1.enabled) {
        if (osc1.lfoTarget === 'pitch') osc1ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc1_pitch')) osc1ModPitch = true;

        if (!osc1ModPitch) {
            const cents = osc1.coarseDetune + osc1.fineDetune;
            osc1StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    if (osc2.enabled && !isVocalMode) {
        if (osc2.lfoTarget === 'pitch') osc2ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc2_pitch')) osc2ModPitch = true;

        if (!osc2ModPitch) {
            const cents = osc2.coarseDetune + osc2.fineDetune;
            osc2StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    if (osc3.enabled && !isVocalMode) {
        if (osc3.lfoTarget === 'pitch') osc3ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc3_pitch')) osc3ModPitch = true;

        if (!osc3ModPitch) {
            const cents = osc3.coarseDetune + osc3.fineDetune;
            osc3StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    // --- LFO DELAY CALCULATION ---
    // Linear fade-in of LFO depth based on activeTime
    this.activeTime += (len * dt);

    // 0.001 to prevent divide by zero
    const lfoFade1 = osc1.lfoDelay ? Math.min(1.0, this.activeTime / Math.max(0.01, osc1.lfoDelay)) : 1.0;
    const lfoFade2 = osc2.lfoDelay ? Math.min(1.0, this.activeTime / Math.max(0.01, osc2.lfoDelay)) : 1.0;
    const lfoFade3 = osc3.lfoDelay ? Math.min(1.0, this.activeTime / Math.max(0.01, osc3.lfoDelay)) : 1.0;

    for (let s = 0; s < len; s++) {
        // --- 1. MODULATORS ---
        anyEnvActive = false;

        // Unrolled Envelope & LFO processing
        // OSC 1
        const env1 = this.envs[0].process(osc1, dt);
        this.envVals[0] = env1;
        if (this.envs[0].stage !== 'idle') anyEnvActive = true;
        this.lfoPhases[0] += lfoRate1 * dt;
        if (this.lfoPhases[0] >= 1.0) this.lfoPhases[0] -= 1.0;
        this.lfoVals[0] = Math.sin(TWO_PI * this.lfoPhases[0]) * lfoFade1;

        // OSC 2
        const env2 = this.envs[1].process(osc2, dt);
        this.envVals[1] = env2;
        if (this.envs[1].stage !== 'idle') anyEnvActive = true;
        this.lfoPhases[1] += lfoRate2 * dt;
        if (this.lfoPhases[1] >= 1.0) this.lfoPhases[1] -= 1.0;
        this.lfoVals[1] = Math.sin(TWO_PI * this.lfoPhases[1]) * lfoFade2;

        // OSC 3
        const env3 = this.envs[2].process(osc3, dt);
        this.envVals[2] = env3;
        if (this.envs[2].stage !== 'idle') anyEnvActive = true;
        this.lfoPhases[2] += lfoRate3 * dt;
        if (this.lfoPhases[2] >= 1.0) this.lfoPhases[2] -= 1.0;
        this.lfoVals[2] = Math.sin(TWO_PI * this.lfoPhases[2]) * lfoFade3;

        if (!anyEnvActive && s === len - 1) {
            this.active = false;
        }

        // --- 2. MOD MATRIX ---
        let modP1=0, modC1=0, modG1=0, modR1=0;
        let modP2=0, modC2=0, modG2=0, modR2=0;
        let modP3=0, modC3=0, modG3=0, modR3=0;

        if (hasMatrix) {
            for(let m = 0; m < matrix.length; m++) {
                const row = matrix[m];
                if (!row.enabled) continue;

                let srcVal = 0;
                // Hardcoded source lookup for speed
                if (row.source === 'env1') srcVal = this.envVals[0];
                else if (row.source === 'env2') srcVal = this.envVals[1];
                else if (row.source === 'env3') srcVal = this.envVals[2];
                else if (row.source === 'lfo1') srcVal = this.lfoVals[0];
                else if (row.source === 'lfo2') srcVal = this.lfoVals[1];
                else if (row.source === 'lfo3') srcVal = this.lfoVals[2];

                const amt = srcVal * row.amount;

                // Hardcoded target lookup
                switch(row.target) {
                    case 'osc1_pitch': modP1 += amt; break;
                    case 'osc1_cutoff': modC1 += amt; break;
                    case 'osc1_gain': modG1 += amt; break;
                    case 'osc1_res': modR1 += amt; break;
                    case 'osc2_pitch': modP2 += amt; break;
                    case 'osc2_cutoff': modC2 += amt; break;
                    case 'osc2_gain': modG2 += amt; break;
                    case 'osc2_res': modR2 += amt; break;
                    case 'osc3_pitch': modP3 += amt; break;
                    case 'osc3_cutoff': modC3 += amt; break;
                    case 'osc3_gain': modG3 += amt; break;
                    case 'osc3_res': modR3 += amt; break;
                }
            }
        }

        // --- 3. VOICE GENERATION ---
        let voiceMix = 0.0;

        // --- OSC 1 (MASTER CARRIER FOR VOCAL) ---
        if (osc1.enabled && this.envVals[0] > 0.0001) {
            let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
            const d = osc1.lfoDepth || 0;
            const v = this.lfoVals[0];
            if (osc1.lfoTarget === 'pitch') hardPitch = v * d;
            else if (osc1.lfoTarget === 'filter') hardFilter = v * d * 20;
            else if (osc1.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

            let freq;
            if (osc1ModPitch) {
                const cents = osc1.coarseDetune + osc1.fineDetune + hardPitch + (modP1 * 1200);
                freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
            } else {
                freq = osc1StaticFreq;
            }

            let sig = this.oscs[0].process(freq, osc1.waveform, dt);

            const cut1 = osc1.filterCutoff + hardFilter + (modC1 * 5000);
            const res1 = Math.max(0, osc1.filterResonance + (modR1 * 10));

            // F1: Standard Filter (Lowpass usually for Vocal Source)
            sig = this.filters[0].process(sig, cut1, res1, this.sampleRate, fType1);

            if (isVocalMode) {
                // Serial Chain: F1 -> F2 -> F3 -> Mix
                // Osc 2 is F2. Use osc2.gain as Peak Gain.
                // Map 0-1 gain to 0-8 boost for powerful resonance
                const gain2 = osc2.gain * 8.0;
                const cut2 = osc2.filterCutoff + (modC2 * 5000);
                const res2 = Math.max(0, osc2.filterResonance + (modR2 * 10));
                sig = this.filters[1].process(sig, cut2, res2, this.sampleRate, fType2, gain2); 

                // Osc 3 is F3. Use osc3.gain as Peak Gain.
                const gain3 = osc3.gain * 8.0;
                const cut3 = osc3.filterCutoff + (modC3 * 5000);
                const res3 = Math.max(0, osc3.filterResonance + (modR3 * 10));
                sig = this.filters[2].process(sig, cut3, res3, this.sampleRate, fType3, gain3); 

                // For vocal mode, we rely on Osc 1 Gain & Env for the master output
                voiceMix += sig * osc1.gain * this.envVals[0] * hardAmp * Math.max(0, 1.0 + modG1);

                // --- ASPIRATION (BREATH NOISE) ---
                // Additive noise layer processed by Highpass Filter
                // It follows the main vocal amplitude envelope (Env 1)
                if (aspirationGain > 0.001) {
                    let noise = (Math.random() * 2.0) - 1.0;
                    // Filter: Highpass (Type 1), Resonance 0.5 (Neutral)
                    noise = this.noiseFilter.process(noise, aspirationCutoff, 0.5, this.sampleRate, 1);
                    // Mix: Scaled by aspirationGain and Envelope 1
                    voiceMix += noise * aspirationGain * this.envVals[0] * hardAmp * 0.5;
                }

            } else {
                // Standard Parallel Mode
                voiceMix += sig * osc1.gain * this.envVals[0] * hardAmp * Math.max(0, 1.0 + modG1);
            }
        }

        if (!isVocalMode) {
            // --- OSC 2 (Standard Mode) ---
            if (osc2.enabled && this.envVals[1] > 0.0001) {
                let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
                const d = osc2.lfoDepth || 0;
                const v = this.lfoVals[1];
                if (osc2.lfoTarget === 'pitch') hardPitch = v * d;
                else if (osc2.lfoTarget === 'filter') hardFilter = v * d * 20;
                else if (osc2.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

                let freq;
                if (osc2ModPitch) {
                    const cents = osc2.coarseDetune + osc2.fineDetune + hardPitch + (modP2 * 1200);
                    freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
                } else {
                    freq = osc2StaticFreq;
                }

                let sig = this.oscs[1].process(freq, osc2.waveform, dt);
                const cut = osc2.filterCutoff + hardFilter + (modC2 * 5000);
                const res = Math.max(0, osc2.filterResonance + (modR2 * 10));
                sig = this.filters[1].process(sig, cut, res, this.sampleRate, fType2);

                voiceMix += sig * osc2.gain * this.envVals[1] * hardAmp * Math.max(0, 1.0 + modG2);
            }

            // --- OSC 3 (Standard Mode) ---
            if (osc3.enabled && this.envVals[2] > 0.0001) {
                let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
                const d = osc3.lfoDepth || 0;
                const v = this.lfoVals[2];
                if (osc3.lfoTarget === 'pitch') hardPitch = v * d;
                else if (osc3.lfoTarget === 'filter') hardFilter = v * d * 20;
                else if (osc3.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

                let freq;
                if (osc3ModPitch) {
                    const cents = osc3.coarseDetune + osc3.fineDetune + hardPitch + (modP3 * 1200);
                    freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
                } else {
                    freq = osc3StaticFreq;
                }

                let sig = this.oscs[2].process(freq, osc3.waveform, dt);
                const cut = osc3.filterCutoff + hardFilter + (modC3 * 5000);
                const res = Math.max(0, osc3.filterResonance + (modR3 * 10));
                sig = this.filters[2].process(sig, cut, res, this.sampleRate, fType3);

                voiceMix += sig * osc3.gain * this.envVals[2] * hardAmp * Math.max(0, 1.0 + modG3);
            }
        }

        // --- 4. FORMANT FILTER (Parallel Bandpass Bank - Legacy or Extra Color) ---
        if (formantStrength > 0.01) {
            const formantSig = this.formantFilter.process(voiceMix, vowelPos, this.sampleRate);
            // Mix Dry/Wet based on formantStrength
            // Note: Formant filter gain can be high, so we might need to compensate volume slightly
            // Usually formants are subtractive in nature (filtering), but parallel bandpass adds energy at peaks.
            voiceMix = (voiceMix * (1.0 - formantStrength)) + (formantSig * formantStrength * 1.5);
        }

        // --- 5. PANNING & OUTPUT ---
        panPhase += dt * panSpeed;
        if (panPhase > 1.0) panPhase -= 1.0;

        const autoPan = Math.sin(panPhase * TWO_PI) * panDepth;
        let p = this.panPos * spreadAmount;
        p += autoPan;
        p = Math.max(-1.0, Math.min(1.0, p));

        // Equal power pan approx
        const gainL = 0.5 * (1.0 - p);
        const gainR = 0.5 * (1.0 + p);

        bufL[s] += voiceMix * gainL * voiceGain;
        bufR[s] += voiceMix * gainR * voiceGain;
    }
  }
}

// --- 4. PROCESSOR LOGIC (Worklet Core) ---

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    // Default to enabled (Store controls this)
    this.isOversamplingEnabled = true;
    this.globalBendMultiplier = 1.0; // Master pitch bend ratio

    // Initial setup
    const OVERSAMPLE = 2;
    const workingRate = sampleRate * OVERSAMPLE;

    this.voices = [];
    // Increase physical voice limit to 64
    for(let i=0; i<64; i++) {
        const v = new Voice(workingRate);
        v.panPos = Math.sin(i * 123.456); 
        this.voices.push(v);
    }

    this.presets = {
        normal: DUMMY_PRESET_DATA,
        latch: DUMMY_PRESET_DATA,
        strum: DUMMY_PRESET_DATA,
        voice: DUMMY_PRESET_DATA,
        arpeggio: DUMMY_PRESET_DATA
    };

    this.maxPolyphony = 32; 
    this.strumDuration = 0.5;

    this.xm1L = 0; this.ym1L = 0;
    this.xm1R = 0; this.ym1R = 0;

    // Global Pan Phase tracker
    this.panPhase = 0;

    // Mix Buffers
    this.mixBufferL = null;
    this.mixBufferR = null;

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'update_preset') {
        const { mode, data } = msg;
        if (mode && this.presets[mode]) {
            this.presets[mode] = this.normalizePreset(data);
        }
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
         if (msg.strumDuration) this.strumDuration = msg.strumDuration;
         if (msg.enableOversampling !== undefined) this.isOversamplingEnabled = msg.enableOversampling;
         if (msg.globalBend !== undefined) this.globalBendMultiplier = msg.globalBend;
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq, msg.voiceType, msg.mode);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => v.hardStop());
      }
    };
  }

  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) },
          osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) },
          osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
          modMatrix: (data.modMatrix || []).map(row => ({
              ...row,
              amount: (Number.isFinite(row.amount) ? row.amount : 0) / 100.0
          })),
          gain: data.gain || 0.5,
          spread: data.spread || 0,
          stereoPanSpeed: data.stereoPanSpeed || 0,
          stereoPanDepth: data.stereoPanDepth || 0,
          formantStrength: (data.formantStrength !== undefined) ? data.formantStrength : 0,
          vowel: (data.vowel !== undefined) ? data.vowel : 0,
          portamento: (data.portamento !== undefined) ? data.portamento : 0,
          aspirationGain: (data.aspirationGain !== undefined) ? data.aspirationGain : 0,
          aspirationCutoff: (data.aspirationCutoff !== undefined) ? data.aspirationCutoff : 4000
      };
  }

  triggerVoice(id, freq, type, mode) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].trigger(id, freq, type, mode);
            return;
        }
    }

    let activeCount = 0;
    let oldestReleased = null;
    let oldestReleaseTime = Infinity;
    let oldestHeld = null;
    let oldestStartTime = Infinity;
    let freeVoice = null;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            activeCount++;
            if (v.releaseTime > 0) {
                if (v.releaseTime < oldestReleaseTime) {
                    oldestReleaseTime = v.releaseTime;
                    oldestReleased = v;
                }
            } else {
                if (v.startTime < oldestStartTime) {
                    oldestStartTime = v.startTime;
                    oldestHeld = v;
                }
            }
        } else {
            if (!freeVoice) freeVoice = v;
        }
    }

    if (activeCount < this.maxPolyphony && freeVoice) {
        freeVoice.trigger(id, freq, type, mode);
        return;
    }

    const victim = oldestReleased || oldestHeld || freeVoice || this.voices[0];
    if (victim) {
        if (victim.active && victim.id !== id) {
             this.port.postMessage({ type: 'voice_stolen', id: victim.id });
        }
        victim.trigger(id, freq, type, mode);
    }
  }

  releaseVoice(id) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
             this.voices[i].targetFreq = freq;
        }
    }
  }

  process(inputs, outputs, parameters) {
    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];
    if (!channelL) return true;
    const len = channelL.length;

    // Config based on Oversampling setting
    const OVERSAMPLE = this.isOversamplingEnabled ? 2 : 1;
    const workingRate = sampleRate * OVERSAMPLE;
    const workingLen = len * OVERSAMPLE;
    const dt = 1.0 / workingRate;

    // Performance Budget
    const startTime = globalThis.performance ? globalThis.performance.now() : 0;
    const MAX_BUDGET_MS = 1.5; 

    // Resize buffer if needed
    if (!this.mixBufferL || this.mixBufferL.length !== workingLen) {
        this.mixBufferL = new Float32Array(workingLen);
        this.mixBufferR = new Float32Array(workingLen);
        // Inform voices of new sample rate for filter/osc calculations
        this.voices.forEach(v => v.updateSampleRate(workingRate));
    }

    this.mixBufferL.fill(0);
    this.mixBufferR.fill(0);

    const masterPreset = this.presets.normal;
    const panSpeed = (masterPreset.stereoPanSpeed !== undefined) ? masterPreset.stereoPanSpeed : 0.0;
    const panDepth = (masterPreset.stereoPanDepth !== undefined) ? masterPreset.stereoPanDepth : 0.0;
    const initialPanPhase = this.panPhase;

    // --- RENDER VOICES ---
    let voicesProcessed = 0;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            // Auto-Release Check for Trigger mode
            if ((v.mode === 'trigger' || v.type === 'strum') && v.releaseTime === 0) {
                if (currentTime - v.startTime >= this.strumDuration) v.release();
            }

            const presetToUse = this.presets[v.type] || this.presets.normal;

            // Pass the global pan parameters to synchronization
            v.renderBlock(presetToUse, dt, this.mixBufferL, this.mixBufferR, workingLen, panSpeed, panDepth, initialPanPhase, this.globalBendMultiplier);
            voicesProcessed++;

            // CPU GOVERNOR
            if (startTime > 0 && voicesProcessed % 2 === 0) {
                if (globalThis.performance.now() - startTime > MAX_BUDGET_MS) {
                    break;
                }
            }
        }
    }

    // Update global pan phase for next block
    this.panPhase += (workingLen * dt * panSpeed);
    while (this.panPhase > 1.0) this.panPhase -= 1.0;

    // --- OUTPUT ---
    if (OVERSAMPLE === 2) {
        // Simple Decimation + Linear DC Blocker
        for (let s = 0; s < len; s++) {
            let accL = 0;
            let accR = 0;
            const osIdx = s * 2;

            // Soft Clip before downsample
            let sl1 = Math.tanh(this.mixBufferL[osIdx] * 0.8);
            let sr1 = Math.tanh(this.mixBufferR[osIdx] * 0.8);
            let sl2 = Math.tanh(this.mixBufferL[osIdx+1] * 0.8);
            let sr2 = Math.tanh(this.mixBufferR[osIdx+1] * 0.8);

            const outL = (sl1 + sl2) * 0.5;
            const outR = (sr1 + sr2) * 0.5;

            // DC Blocker
            const yL = outL - this.xm1L + 0.995 * this.ym1L;
            this.xm1L = outL;
            this.ym1L = yL;

            const yR = outR - this.xm1R + 0.995 * this.ym1R;
            this.xm1R = outR;
            this.ym1R = yR;

            channelL[s] = yL;
            if (channelR) channelR[s] = yR;
        }
    } else {
        // 1x Passthrough
        for (let s = 0; s < len; s++) {
            // Soft Clip
            const sl = Math.tanh(this.mixBufferL[s] * 0.8);
            const sr = Math.tanh(this.mixBufferR[s] * 0.8);

            // DC Blocker
            const yL = sl - this.xm1L + 0.995 * this.ym1L;
            this.xm1L = sl;
            this.ym1L = yL;

            const yR = sr - this.xm1R + 0.995 * this.ym1R;
            this.xm1R = sr;
            this.ym1R = yR;

            channelL[s] = yL;
            if (channelR) channelR[s] = yR;
        }
    }

    return true;
  }
}

